#!/usr/bin/env bash
# Doc développeur : la partie « Les envois de fichiers », en quatre chapitres.
# Prérequis : apply-fix-envois.sh.
# Usage (racine du repo) : bash apply-docs-envois.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/index.mdx" 2>/dev/null | grep -qF "Toutes les portes par où un fichier entre"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Les envois de fichiers" "apps/web/src/features/docs/lib/docs.navigation.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-envois.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/finder/trois-finders-en-un.mdx" "apps/web/content/docs/dev/index.mdx")
CREATED=("apps/web/content/docs/dev/envois/sept-portes-trois-familles.mdx" "apps/web/content/docs/dev/envois/les-formulaires-de-lot.mdx" "apps/web/content/docs/dev/envois/les-photos-d-iphone.mdx" "apps/web/content/docs/dev/envois/un-fichier-un-usage.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/envois" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "Toutes les portes par où un fichier entre" "apps/web/content/docs/dev/index.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/envois"
